import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { overdueInvoices } from '../src/reports.js';

test('overdueInvoices returns empty array for null invoices', () => {
  const r = overdueInvoices(null, '2026-10-31');
  assert.deepEqual(r, []);
});

test('overdueInvoices returns empty array for empty invoices', () => {
  const r = overdueInvoices([], '2026-10-31');
  assert.deepEqual(r, []);
});

test('overdueInvoices excludes draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const r = overdueInvoices([invoice.value], '2026-11-01');
  assert.equal(r.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.value.total, date: '2026-10-10' });
  const r = overdueInvoices([paid.value], '2026-11-01');
  assert.equal(r.length, 0);
});

test('overdueInvoices includes issued invoices past due date', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const r = overdueInvoices([issued.value], '2026-10-22');
  assert.equal(r.length, 1);
  assert.equal(r[0].number, issued.value.number);
  assert.equal(r[0].customerId, 'C-001');
  assert.equal(r[0].dueDate, '2026-10-21');
});

test('overdueInvoices includes partially_paid invoices past due date', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 5 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const partial = recordPayment(issued.value, { amount: 30, date: '2026-10-10' });
  const r = overdueInvoices([partial.value], '2026-10-22');
  assert.equal(r.length, 1);
  assert.equal(r[0].number, partial.value.number);
});

test('overdueInvoices excludes invoices not yet due', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const r = overdueInvoices([issued.value], '2026-10-21');
  assert.equal(r.length, 0);
});

test('overdueInvoices excludes invoices due on asOf date', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const r = overdueInvoices([issued.value], '2026-10-21');
  assert.equal(r.length, 0);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const r = overdueInvoices([issued.value], '2026-10-28');
  assert.equal(r.length, 1);
  assert.equal(r[0].daysOverdue, 7);
});

test('overdueInvoices calculates due amount correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const r = overdueInvoices([issued.value], '2026-10-22');
  assert.equal(r.length, 1);
  assert.equal(r[0].due, totals.value.total);
});

test('overdueInvoices calculates due amount after partial payment', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 5 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const partial = recordPayment(issued.value, { amount: 30, date: '2026-10-10' });
  const r = overdueInvoices([partial.value], '2026-10-22');
  assert.equal(r.length, 1);
  assert.equal(r[0].due, totals.value.total - 30);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const invoice2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-10',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);

  const invoice3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-05',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued3 = issueInvoice(invoice3.value, ['INV-2026-0001', 'INV-2026-0002']);

  const r = overdueInvoices([issued1.value, issued2.value, issued3.value], '2026-10-31');
  assert.equal(r.length, 3);
  assert.equal(r[0].daysOverdue, 16); // Oct 1 + 14 = Oct 15, overdue by 16 days on Oct 31
  assert.equal(r[1].daysOverdue, 7); // Oct 5 + 14 = Oct 19, overdue by 12 days on Oct 31
  assert.equal(r[2].daysOverdue, 7); // Oct 10 + 14 = Oct 24, overdue by 7 days on Oct 31
});

test('overdueInvoices with multiple invoices from same customer', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'STICKER', qty: 2 }],
    terms: 'NET14',
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);

  const r = overdueInvoices([issued1.value, issued2.value], '2026-10-31');
  assert.equal(r.length, 2);
  assert.equal(r[0].customerId, 'C-001');
  assert.equal(r[1].customerId, 'C-001');
});

test('overdueInvoices returns all required fields', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const r = overdueInvoices([issued.value], '2026-10-22');
  assert.equal(r.length, 1);
  assert.ok('number' in r[0]);
  assert.ok('customerId' in r[0]);
  assert.ok('dueDate' in r[0]);
  assert.ok('daysOverdue' in r[0]);
  assert.ok('due' in r[0]);
});

test('overdueInvoices with mixed issued and draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });

  const issued = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issuedInv = issueInvoice(issued.value, []);

  const r = overdueInvoices([draft.value, issuedInv.value], '2026-10-31');
  assert.equal(r.length, 1);
  assert.equal(r[0].customerId, 'C-002');
});

test('overdueInvoices with various payment amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const payment1 = recordPayment(issued.value, { amount: 20000, date: '2026-10-10' });
  const payment2 = recordPayment(payment1.value, { amount: 15000, date: '2026-10-15' });
  const r = overdueInvoices([payment2.value], '2026-10-22');
  assert.equal(r.length, 1);
  assert.equal(r[0].due, totals.value.total - 20000 - 15000);
});

test('overdueInvoices does not include invoices by one day off', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const r = overdueInvoices([issued.value], '2026-10-21');
  assert.equal(r.length, 0);
});

test('overdueInvoices includes invoice on first day overdue', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const r = overdueInvoices([issued.value], '2026-10-22');
  assert.equal(r.length, 1);
  assert.equal(r[0].daysOverdue, 1);
});

test('overdueInvoices with EOM terms', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'EOM',
  });
  const issued = issueInvoice(invoice.value, []);
  const r = overdueInvoices([issued.value], '2026-11-01');
  assert.equal(r.length, 1);
  assert.equal(r[0].dueDate, '2026-10-31');
  assert.equal(r[0].daysOverdue, 1);
});

test('overdueInvoices with NET30 terms', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET30',
  });
  const issued = issueInvoice(invoice.value, []);
  const r = overdueInvoices([issued.value], '2026-11-08');
  assert.equal(r.length, 1);
  assert.equal(r[0].dueDate, '2026-11-06');
  assert.equal(r[0].daysOverdue, 2);
});

test('overdueInvoices returns copy of data', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const r1 = overdueInvoices([issued.value], '2026-10-22');
  const r2 = overdueInvoices([issued.value], '2026-10-22');
  assert.notStrictEqual(r1, r2);
  assert.deepEqual(r1, r2);
});

test('overdueInvoices handles large number of invoices', () => {
  const invoices = Array.from({ length: 100 }, (_, i) => {
    const invoice = createInvoice({
      customerId: `C-${String(i % 10).padStart(3, '0')}`,
      issueDate: `2026-${String((i % 11) + 1).padStart(2, '0')}-${String((i % 28) + 1).padStart(2, '0')}`,
      lines: [{ sku: 'STICKER', qty: 1 }],
      terms: 'NET14',
    });
    return issueInvoice(invoice.value, []);
  });
  const r = overdueInvoices(invoices.map((inv) => inv.value), '2026-11-30');
  assert.ok(r.length > 0);
  for (let i = 1; i < r.length; i++) {
    assert.ok(r[i - 1].daysOverdue >= r[i].daysOverdue);
  }
});

test('overdueInvoices with negative daysOverdue should not occur', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const r = overdueInvoices([issued.value], '2026-10-20');
  assert.equal(r.length, 0);
});

test('overdueInvoices preserves customerId across filtering', () => {
  const invoice1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const r = overdueInvoices([issued1.value], '2026-10-22');
  assert.equal(r.length, 1);
  assert.equal(r[0].customerId, 'C-003');
});

test('overdueInvoices with fully paid then more payment', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const payment1 = recordPayment(issued.value, { amount: totals.value.total, date: '2026-10-10' });
  const r = overdueInvoices([payment1.value], '2026-10-22');
  assert.equal(r.length, 0);
});

